package local.cleartv.mobile;
import android.content.Context;import java.net.*;import java.io.*;import java.util.*;import java.security.*;import java.util.concurrent.*;import org.json.*;
public final class RemoteCheck{
 static byte[] frame(InputStream in)throws Exception{int a=in.read(),b=in.read();if((b&128)==0)throw new Exception("Client frame is not masked");int len=b&127;if(len==126)len=(in.read()<<8)|in.read();if(len>=65536)throw new Exception("Unexpected frame size");byte[] mask=SdbClient.exact(in,4),data=SdbClient.exact(in,len);for(int i=0;i<len;i++)data[i]^=mask[i%4];return data;}
 public static void run(Context context)throws Exception{
  String ip=Network.phoneIP();if(ip.isEmpty())throw new Exception("No local interface for loopback test");CompletableFuture<String> outcome=new CompletableFuture<>();
  try(ServerSocket listener=new ServerSocket(8001)){
   Thread server=new Thread(()->{try(Socket s=listener.accept()){s.setSoTimeout(5000);InputStream in=s.getInputStream();ByteArrayOutputStream head=new ByteArrayOutputStream();int tail=0;while(head.size()<16384){int c=in.read();if(c<0)throw new EOFException();head.write(c);tail=(tail<<8)|c;if(tail==0x0d0a0d0a)break;}String headers=head.toString("US-ASCII");if(!headers.contains("?name="))throw new Exception("Websocket query lost");String key="";for(String line:headers.split("\r\n"))if(line.toLowerCase(Locale.US).startsWith("sec-websocket-key:"))key=line.substring(line.indexOf(':')+1).trim();String accept=Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-1").digest((key+"258EAFA5-E914-47DA-95CA-C5AB0DC85B11").getBytes("US-ASCII")));OutputStream out=s.getOutputStream();out.write(("HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: "+accept+"\r\n\r\n").getBytes("US-ASCII"));byte[] event="{\"event\":\"ms.channel.connect\",\"data\":{}}".getBytes("UTF-8");out.write(129);out.write(event.length);out.write(event);out.flush();JSONObject command=new JSONObject(new String(frame(in),"UTF-8"));if(!command.getJSONObject("params").getString("DataOfCmd").equals("KEY_UP"))throw new Exception("Wrong key payload");command=new JSONObject(new String(frame(in),"UTF-8"));String text=new String(Base64.getDecoder().decode(command.getJSONObject("params").getString("Cmd")),"UTF-8");if(!text.equals("الأهلي TV Morph"))throw new Exception("Arabic text changed");outcome.complete("PASS");}catch(Throwable e){outcome.completeExceptionally(e);}},"remote-test-server");server.start();
   try(SamsungRemote client=new SamsungRemote(context,ip)){client.key("UP");client.text("الأهلي TV Morph");if(!outcome.get(8,TimeUnit.SECONDS).equals("PASS"))throw new Exception("Protocol test failed");}
  }
 }
}
